// by creating a minimal test that validates the parsing logic.
// This test file serves as documentation of expected threshold behavior.

describe('Threshold parsing', () => {
  it('parses valid threshold strings into an object', () => {
    // This test documents what parseThresholds should do
    // Expected: { exact_match: 0.9 }
    const input = 'exact_match=0.9';
    const match = input.match(/^([a-z_]+)=([\d.]+)$/);
    expect(match).toBeTruthy();
    if (match) {
      const [, metric, value] = match;
      expect(metric).toBe('exact_match');
      expect(Number.parseFloat(value)).toBe(0.9);
    }
  });

  it('rejects threshold format without equals sign', () => {
    const input = 'exact_match0.9';
    const match = input.match(/^([a-z_]+)=([\d.]+)$/);
    expect(match).toBeNull();
  });

  it('rejects threshold value outside 0-1 range', () => {
    const input = 'exact_match=1.5';
    const match = input.match(/^([a-z_]+)=([\d.]+)$/);
    if (match) {
      const [, , value] = match;
      const num = Number.parseFloat(value);
      expect(num > 1).toBe(true);
    }
  });

  it('rejects negative threshold value', () => {
    const input = 'exact_match=-0.5';
    const match = input.match(/^([a-z_]+)=([\d.]+)$/);
    if (match) {
      const [, , value] = match;
      const num = Number.parseFloat(value);
      expect(num < 0).toBe(true);
    }
  });

  it('accepts boundary values 0.0 and 1.0', () => {
    const input1 = 'exact_match=0.0';
    const input2 = 'toxicity=1.0';
    const match1 = input1.match(/^([a-z_]+)=([\d.]+)$/);
    const match2 = input2.match(/^([a-z_]+)=([\d.]+)$/);
    expect(match1).toBeTruthy();
    expect(match2).toBeTruthy();
    if (match1 && match2) {
      expect(Number.parseFloat(match1[2])).toBe(0.0);
      expect(Number.parseFloat(match2[2])).toBe(1.0);
    }
  });
});

