477	function parseThresholds(thresholdStrings: string[] = []): Record<string, number> | undefined {
478	  if (!thresholdStrings.length) return undefined;
479	  const result: Record<string, number> = {};
480	  thresholdStrings.forEach((str) => {
481	    const match = str.match(/^([a-z_]+)=([\d.]+)$/);
482	    if (!match) {
483	      throw new Error(`Invalid threshold format: "${str}". Expected format: <metric>=<number>`);
484	    }
485	    const [, metric, value] = match;
486	    const num = Number.parseFloat(value);
487	    if (Number.isNaN(num) || num < 0 || num > 1) {
488	      throw new Error(`Invalid threshold value for "${metric}": ${value}. Must be a number between 0 and 1.`);
489	    }
490	    result[metric] = num;
491	  });
492	  return result;
493	}
