62	function evaluateThresholds(evaluations, thresholds) {
63	  if (!thresholds || Object.keys(thresholds).length === 0) {
64	    return { passed: true, thresholds: [] };
65	  }
66	
67	  const metricsById = new Map(evaluations.map((m) => [m.id, m]));
68	  const thresholdResults = [];
69	  let allPassed = true;
70	
71	  for (const [metricId, minScore] of Object.entries(thresholds)) {
72	    const metric = metricsById.get(metricId);
73	    if (!metric) {
74	      const validIds = Array.from(metricsById.keys()).join(', ');
75	      throw new Error(`Unknown metric id: "${metricId}". Valid metrics: ${validIds}`);
76	    }
77	
78	    const score = metric.score;
79	    const passed = score !== null && score >= minScore;
80	    if (!passed) allPassed = false;
81	
82	    thresholdResults.push({
83	      metric: metricId,
84	      min: minScore,
85	      score,
86	      passed
87	    });
88	  }
89	
90	  return { passed: allPassed, thresholds: thresholdResults };
91	}
