93	export function generateReport({
94	  evaluations,
95	  outputsPath,
96	  referencesPath,
97	  thresholds,
98	  generatedAt = new Date().toISOString()
99	}) {
100	  const totalSamples = evaluations.reduce((total, metric) => {
101	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
102	    return total;
103	  }, 0);
104	
105	  const thresholdEvaluation = evaluateThresholds(evaluations, thresholds);
106	
107	  return {
108	    metadata: {
109	      generatedAt,
110	      outputsPath,
111	      referencesPath,
112	      totalSamples
113	    },
114	    metrics: evaluations,
115	    passed: thresholdEvaluation.passed,
116	    thresholds: thresholdEvaluation.thresholds
117	  };
118	}
